v2.launcher_source:
$ErrorActionPreference='Stop'
$errors=$null;$tokens=$null
[Management.Automation.Language.Parser]::ParseFile('D:\upmix\tools\run_spectral_context_fit.ps1',[ref]$tokens,[ref]$errors)|Out-Null
if($errors.Count){$errors|ForEach-Object{$_.Message};throw 'Runner parse failed'}
$wrapper=Join-Path $env:TEMP 'upmix_spectral_context_wrapper_v2.ps1'
$log=Join-Path $env:TEMP 'upmix_spectral_context_live_v2.log'
if((Test-Path $wrapper) -or (Test-Path $log)){throw 'Preserve prior launch'}
$content=@"
`$ErrorActionPreference='Stop'
try { & 'D:\upmix\tools\run_spectral_context_fit.ps1' *> '$log'; exit 0 } catch { `$_ | Out-File -Append '$log'; exit 1 }
"@
[IO.File]::WriteAllText($wrapper,$content,[Text.Encoding]::UTF8)
$r=Invoke-CimMethod -ClassName Win32_Process -MethodName Create -Arguments @{CommandLine="powershell.exe -NoProfile -ExecutionPolicy Bypass -File $wrapper"}
@{return_value=$r.ReturnValue;supervisor_pid=$r.ProcessId;log=$log}|ConvertTo-Json -Compress
if($r.ReturnValue -ne 0){throw 'Detached spectral-context launch failed'}
